const isVersionableItemType = options.itemType['is_versionable'] === '1';
if (!isVersionableItemType) {
	return { hidden: true };
}

const queryTypeResources = {
	'Current': 'searchview.commandbar.querytype.current',
	'Latest': 'searchview.commandbar.querytype.latest',
	'Released': 'searchview.commandbar.querytype.released',
	'Effective': 'searchview.commandbar.querytype.effective'
};
const queryTypeOptions = Object.keys(queryTypeResources);
const { queryType } = options.getState();

return {
	value: queryType,
	options: queryTypeOptions.map(function(value) {
		const resource = queryTypeResources[value];
		const label = aras.getResource('', resource);
		return { value, label };
	})
};
